test.describe('REQ-1-3-2 export the current worksheet', () => {
  test('downloads the used range with LF endings and leaves the editor state unchanged', async ({
    page,
  }) => {
    await importCsv(page, 'export basic.csv', ['Region,Sales', 'East,1200', 'North,800'].join('\n'));

    const lastUpdated = page.locator('#workbook-last-updated');
    const updatedBefore = await lastUpdated.textContent();
    const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
    const formulaBefore = await formulaBar.inputValue();
    await expectCellText(page, 'B2', '1200');

    const { fileName, csv } = await exportCsv(page);

    expect(fileName).toMatch(/\.csv$/);
    expect(csv).toBe('Region,Sales\nEast,1200\nNorth,800\n');
    expect(csv.startsWith('\uFEFF')).toBe(false);
    expect(csv.includes('\r')).toBe(false);

    // Export changes nothing: active worksheet, grid values, formula bar, last-updated.
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expectCellText(page, 'B2', '1200');
    await expect(formulaBar).toHaveValue(formulaBefore);
    await expect(lastUpdated).toHaveText(updatedBefore ?? '');

    await page.reload();
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expectCellText(page, 'B2', '1200');
    await expect(lastUpdated).toHaveText(updatedBefore ?? '');
  });

  test('escapes commas, quotes and line breaks and keeps empty cells inside the used range', async ({
    page,
  }) => {
    const csv = ['plain,"with,comma"', '"say ""hi""","line', 'break",,tail'].join('\n');
    await importCsv(page, 'export escaping.csv', csv);

    const { csv: exported } = await exportCsv(page);
    expect(exported).toBe(`plain,"with,comma",,\n"say ""hi""","line\nbreak",,tail\n`);
  });

  test('exports an empty file for a blank workbook', async ({ page }) => {
    await createWorkbook(page, 'Empty export source');
    const { fileName, csv } = await exportCsv(page);
    expect(fileName).toMatch(/\.csv$/);
    expect(csv).toBe('');
